package com.teletronics.storage.domain.file;

import java.util.UUID;

/**
 * A file's identity, generated by the domain so it doesn't depend on the database.
 */
public record FileId(String value) {

    public FileId {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException("file id must not be blank");
        }
    }

    public static FileId newId() {
        return new FileId(UUID.randomUUID().toString());
    }
}
